import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.resolve(__dirname, 'data');

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata for a file under the workspace data directory: relative path, byte size, and lowercase extension. Does not expose file contents.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description: 'Relative path to a file within the data directory.'
          }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'file_metadata') {
    throw new Error('Unknown tool: ' + name);
  }
  args = args || {};
  const p = args.path;
  if (typeof p !== 'string' || p.length === 0) {
    throw new Error('path is required');
  }
  const resolved = path.resolve(DATA_DIR, p);
  // Reject traversal outside data dir
  const rel = path.relative(DATA_DIR, resolved);
  if (rel.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error('Path is outside the data directory');
  }
  let stat;
  try {
    stat = fs.statSync(resolved);
  } catch (e) {
    throw new Error('File not found: ' + p);
  }
  if (!stat.isFile()) {
    throw new Error('Not a file: ' + p);
  }
  const ext = path.extname(resolved).toLowerCase();
  const text = `path: ${rel}\nsize: ${stat.size} bytes\nextension: ${ext}`;
  return {
    content: [{ type: 'text', text }]
  };
}
